      s.innerHTML = `
        <h2 class="screen-title">选择游戏模式</h2>
        <div class="mode-grid" id="mode-grid"></div>
        <div class="screen-actions" id="mode-actions"></div>`;
      const grid = s.querySelector('#mode-grid');
